#include FLOYD_SOURCE
#include <chrono>
#include <iostream>
#include <random>
#include <string>
using Matrix=std::vector<std::vector<std::int64_t>>;
int main(int argc,char**argv){
 const int n=std::stoi(argv[1]);const std::string kind=argv[2];const int repeats=std::stoi(argv[3]);std::mt19937_64 rng(987);
 Matrix source(n,std::vector<std::int64_t>(n,INF));for(int i=0;i<n;++i){source[i][i]=0;for(int j=0;j<n;++j)if(i!=j&&(kind!="sparse"||rng()%100<2))source[i][j]=1+rng()%100000;}
 if(kind=="negative"||kind=="dag")for(int i=0;i<n;++i)for(int j=0;j<n;++j)if(source[i][j]!=INF)source[i][j]+=std::int64_t(j-i)*1000;
 if(kind=="dag")for(int i=0;i<n;++i)for(int j=0;j<i;++j)source[i][j]=INF;
 if(kind=="cycle"&&n>1)source[0][1]=source[1][0]=-100000;
 if(kind=="wide")for(int i=0;i<n;++i)for(int j=0;j<n;++j)if(source[i][j]!=INF&&i!=j)source[i][j]=(i<j?INF/2:1);
 std::uint64_t sum=0;std::int64_t elapsed=0;for(int r=0;r<repeats;++r){auto d=source;std::vector<std::vector<int>> path;auto begin=std::chrono::steady_clock::now();bool negative=kind=="path"?FloydWarshall(d,path):FloydWarshall(d);auto end=std::chrono::steady_clock::now();elapsed+=std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count();sum+=negative;for(const auto&row:d)for(auto v:row)sum=sum*31+static_cast<std::uint64_t>(v);for(const auto&row:path)for(int v:row)sum=sum*31+static_cast<unsigned>(v);}
 std::cout<<"{\"ns\":"<<elapsed/repeats<<",\"checksum\":"<<sum<<"}\n";
}
